/* @autogenerated */
import { Logger } from '@shared/context/observability/logger.service';
import {
  Component,
  HostBinding,
  Inject,
  HostListener,
  Injector,
  OnDestroy,
  OnInit,
  Signal,
  signal,
} from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { AppStateService } from '@shared/context/state/app-state.service';
import { LayoutStateService } from './bootstrap/layout/layout-state.service';
import { menu } from './bootstrap/menu.config';
import { InstrumentationService } from '@shared/context/observability/instrumentation.service';
import { Subscription, take } from 'rxjs';
import { IdentityService } from '@shared/context/identity/identity.service';
import { MenuItem } from './bootstrap/layout/menu-item.model';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { toSignal } from '@angular/core/rxjs-interop';
import { CommonModule, DOCUMENT } from '@angular/common';
import { MenuComponent } from './bootstrap/layout/menu/menu.component';
import { ToolbarComponent } from './bootstrap/layout/toolbar/toolbar.component';
import { FooterComponent } from './bootstrap/layout/footer/footer.component';
import { BootstrapComponent } from './bootstrap/layout/pages/bootstrap/bootstrap.component';
import { SelectorProvider } from '@shared/data/selector-provider';
import { contextProviders } from './bootstrap/context.config';
import { LAYOUT_MOBILE_QUERY } from './bootstrap/layout/layout.constants';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    RouterOutlet,
    TranslocoModule,
    CommonModule,
    MenuComponent,
    ToolbarComponent,
    FooterComponent,
    BootstrapComponent,
  ],
  templateUrl: './app.component.html',
  styleUrl: './app.component.scss',
})
export class AppComponent implements OnInit, OnDestroy {
  currentUser: Signal<UserInfo>;
  currentMenu: Signal<MenuItem[]>;

  mobile = signal(false);

  @HostBinding('class.nav-full') navFull = true;
  @HostBinding('class.nav-mini') navMini = false;
  @HostBinding('class.nav-hide') navHide = false;

  @HostBinding('class.header-compact') headerCompact = false;
  @HostBinding('class.header-hide') headerHide = false;

  @HostBinding('class.nav-overlay-open') navOverlayOpen = false;

  visibleMenu = false;
  menuStyle = 'full';
  bootstrap = false;
  bootstrapError = false;
  contextProviders: { [key: string]: SelectorProvider<any, any> };

  private susbcription = new Subscription();

  constructor(
    transloco: TranslocoService,
    appState: AppStateService,
    instrumentation: InstrumentationService,
    layoutState: LayoutStateService,
    private readonly identity: IdentityService,
    private readonly logger: Logger,
    injector: Injector,
    @Inject(DOCUMENT) document: Document,
  ) {
    instrumentation.activate();
    this.currentUser = appState.user('main');
    this.currentMenu = layoutState.menu;
    this.contextProviders = contextProviders(injector);

    appState.language$.subscribe((lang) => {
      transloco.setActiveLang(lang);
      // Lectores de pantalla y traductores automáticos usan el idioma activo
      document.documentElement.lang = lang;
    });
    layoutState.menu.set(menu());
  }

  get isMobile() {
    return matchMedia(LAYOUT_MOBILE_QUERY).matches;
  }

  get navMode(): 'full' | 'mini' | 'hide' {
    return this.navFull ? 'full' : this.navMini ? 'mini' : 'hide';
  }

  toggleNav() {
    if (this.isMobile) this.navOverlayOpen = !this.navOverlayOpen;
    else if (this.navFull) {
      this.navFull = false;
      this.navMini = true;
      this.navHide = false;
    } else if (this.navMini) {
      this.navFull = false;
      this.navMini = false;
      this.navHide = true;
    } else {
      this.navFull = true;
      this.navMini = false;
      this.navHide = false;
    }
  }

  closeOverlay() {
    this.navOverlayOpen = false;
  }

  @HostListener('document:keydown.escape') onEsc() {
    if (this.isMobile && this.navOverlayOpen) this.closeOverlay();
  }

  ngOnInit(): void {
    this.susbcription.add(
      this.identity
        .bootstrap('main')
        .pipe(take(1))
        .subscribe({
          next: () => (this.bootstrap = true),
          error: (err) => {
            this.logger.error('Identity bootstrap failed', err);
            this.bootstrapError = true;
          },
        }),
    );
  }

  ngOnDestroy(): void {
    this.susbcription.unsubscribe();
  }
}
